detaileddescription.para:
Usage example: //CreateanewFTPclient
sf::Ftpftp;

//Gettheaddressoftheserver
constautoaddresses=sf::Dns::resolve("ftp.myserver.com");

//Checkifwehaveavalidaddress
//RobustcodeshouldadditionallyensurethattheaddressisIPv4
//sincesf::FtpdoesnotsupportconnectingtoIPv6addresses
if(!addresses.has_value()||addresses->empty())
{
//Handlenovalidaddress...
}

//Connecttotheserver
sf::Ftp::Responseresponse=ftp.connect(addresses->front());
if(response.isOk())
std::cout<<"Connected"<<std::endl;

//Login
response=ftp.login("laurent","dF6Zm89D");
if(response.isOk())
std::cout<<"Loggedin"<<std::endl;

//Printtheworkingdirectory
sf::Ftp::DirectoryResponsedirectory=ftp.getWorkingDirectory();
if(directory.isOk())
std::cout<<"Workingdirectory:"<<directory.getDirectory()<<std::endl;

//Createanewdirectory
response=ftp.createDirectory("files");
if(response.isOk())
std::cout<<"Creatednewdirectory"<<std::endl;

//Uploadafiletothisnewdirectory
response=ftp.upload("local-path/file.txt","files",sf::Ftp::TransferMode::Ascii);
if(response.isOk())
std::cout<<"Fileuploaded"<<std::endl;

//Sendspecificcommands(here:FEATtolistsupportedFTPfeatures)
response=ftp.sendCommand("FEAT");
if(response.isOk())
std::cout<<"Featurelist:\n"<<response.getMessage()<<std::endl;

//Disconnectfromtheserver(optional)
ftp.disconnect();
